<?php if (!defined('ABSPATH')) exit; $bid=(int)$bolao->id; if(isset($_POST['rsb_pay']) && check_admin_referer('rsb_pay')){ RSB_Pagamentos::mark((int)$_POST['participante_id'],sanitize_text_field($_POST['status']), (float)$_POST['valor_pago'], sanitize_text_field($_POST['data_pagamento'])); echo '<div class="notice notice-success"><p>Pagamento atualizado.</p></div>'; } $items=RSB_Participantes::all($bid); ?><div class="wrap rsb-wrap"><h1>Pagamentos</h1><form method="post" class="rsb-inline"><?php wp_nonce_field('rsb_pay'); ?><select name="participante_id"><?php foreach($items as $i): ?><option value="<?php echo esc_attr($i->id); ?>"><?php echo esc_html($i->nome); ?></option><?php endforeach; ?></select><select name="status"><option value="pago">Pago</option><option value="pendente">Pendente</option></select><input type="number" step="0.01" name="valor_pago" placeholder="Valor"><input type="date" name="data_pagamento"><button class="button button-primary" name="rsb_pay" value="1">Salvar</button></form><p><strong>Total arrecadado:</strong> <?php echo esc_html(rsb_money(RSB_Pagamentos::total($bid))); ?></p></div>
